static char sx__str491[]="build";
static char sx__str492[]="build - Build using a configuration from sx.mod";
static char sx__str493[]="";
static char sx__str494[]="usage:";
static char sx__str495[]="  spectre build [config]";
static char sx__str496[]="";
static char sx__str497[]="The configuration name defaults to \"dev\".";
static char sx__str498[]="sx.mod must contain a spectre_version that matches the installed";
static char sx__str499[]="compiler, or the build is rejected. A build configuration may also";
static char sx__str500[]="define compile-time environment variables with an env { } block.";
static char sx__str501[]="install";
static char sx__str502[]="install - Build and install a Spectre project from a repository";
static char sx__str503[]="";
static char sx__str504[]="usage:";
static char sx__str505[]="  spectre install <git-url> [-config <name>] [-shell <shell>]";
static char sx__str506[]="                [-bin-dir <dir>]";
static char sx__str507[]="";
static char sx__str508[]="options:";
static char sx__str509[]="  -config <name>  Build configuration to use (default: prod, then";
static char sx__str510[]="                  production, release, default, dev, then the first";
static char sx__str511[]="                  configuration in sx.mod)";
static char sx__str512[]="  -shell <shell>  Shell to configure PATH for (bash, zsh, fish,";
static char sx__str513[]="                  nushell, elvish, powershell, sh, ksh, tcsh, ...)";
static char sx__str514[]="                  Use 'all' to write every supported integration.";
static char sx__str515[]="  -bin-dir <dir>  Override the install directory";
static char sx__str516[]="  -h, -help       Show this help message";
static char sx__str517[]="";
static char sx__str518[]="The repository is cloned to a temporary directory, built with the";
static char sx__str519[]="installed Spectre compiler, and the resulting executable is copied";
static char sx__str520[]="into a Spectre-owned binary directory:";
static char sx__str521[]="  ~/.local/share/spectre/bin";
static char sx__str522[]="";
static char sx__str523[]="That directory is then added to PATH for the selected shell.";
static char sx__str524[]="run";
static char sx__str525[]="run - Compile and immediately run a program";
static char sx__str526[]="";
static char sx__str527[]="usage:";
static char sx__str528[]="  spectre run <input.sx> [options]";
static char sx__str529[]="";
static char sx__str530[]="Compiler options after the input file are applied before running.";
static char sx__str531[]="doc";
static char sx__str532[]="doc - Generate documentation for a source file";
static char sx__str533[]="";
static char sx__str534[]="usage:";
static char sx__str535[]="  spectre doc [path] [-o <dir>] [-md] [-read <file>]";
static char sx__str536[]="";
static char sx__str537[]="options:";
static char sx__str538[]="  -o <dir>     Write documentation to <dir> instead of the default";
static char sx__str539[]="  -md          Generate Markdown instead of HTML";
static char sx__str540[]="  -read <file> Use <file> (relative to the current directory) as the";
static char sx__str541[]="               overview page instead of the target's README";
static char sx__str542[]="  -h, -help    Show this help message";
static char sx__str543[]="";
static char sx__str544[]="The path defaults to the current directory. Without -o, a directory";
static char sx__str545[]="target is written to ./docs-out-<name>/, where <name> is the last";
static char sx__str546[]="path component. A single .sx target is written to ./docs-out/.";
static char sx__str547[]="The output directory is created if it does not exist.";
